<?php
require_once(__DIR__.'/../../../../util/utils.php'); class med_cisz_bundle_builder { use med_cisz_utilsTrait; private med_cisz_context $context; public function __construct(med_cisz_context $context) { $this->context = $context; } public function build(object $data): object { $entries = $data->entries ?? []; if (empty($entries)) { throw new Exception("No entries found"); } $data->id = $data->id ?? generateUUID(null, null, true); $patient = $this->context->getPatient(); $patientResource = $patient->profile ?? null; $conditionResource = $this->getCompositionResource($data); $bundleEntries = [$conditionResource, $patientResource, ...$entries]; return (object) [ 'resourceType' => 'Bundle', 'id' => $data->id, 'meta' => (object) [ 'profile' => [med_cisz_constant::$structureDefinitions['MedicationDocument']] ], 'identifier' => (object) [ 'system' => 'urn:ietf:rfc:3986', 'value' => 'urn:uuid:' . generateUUID(null, null, true) ], 'type' => 'document', 'timestamp' => date('c'), 'entry' => $bundleEntries ]; } private function getCompositionResource(object $data): object { $patient = $this->context->getPatient(); $organization = $this->context->getOrganization(); $practitioner = $this->context->getPractitioner(); return (object) [ 'fullUrl' => 'Composition/' . $data->id, 'resource' => (object) [ 'resourceType' => 'Composition', 'id' => $data->id, 'meta' => (object) [ 'profile' => [med_cisz_constant::$structureDefinitions['CompDocument']] ], 'status' => 'final', 'type' => self::getCodingStructure(med_cisz_constant::$valueSet['CompositionType'], 'general'), 'subject' => [$patient->link], 'date' => date('c'), 'author' => [$practitioner->link], 'title' => med_cisz_constant::DEFAULT_BUNDLE_TITLE, 'custodian' => $organization->link, ], ]; } }